// Array implementation of Stack\nclass Stack {
  constructor(capacity) {
    this.items = [];
    this.capacity = capacity;
    this.top = -1;
  }

  // Push operation\n  push(element) {
    if (this.isFull()) {
      console.log('Stack Overflow');
      return;
    }
    this.items.push(element);
    this.top++;
    console.log(element + ' pushed to stack');
  }

  // Pop operation\n  pop() {
    if (this.isEmpty()) {
      console.log('Stack Underflow');
      return null;
    }
    const element = this.items.pop();
    this.top--;
    return element;
  }

  // Peek operation\n  peek() {
    if (this.isEmpty()) {
      console.log('Stack is empty');
      return null;
    }
    return this.items[this.items.length - 1];
  }

  // Check if stack is empty\n  isEmpty() {
    return this.top === -1;
  }

  // Check if stack is full\n  isFull() {
    return this.top === this.capacity - 1;
  }

  // Display stack\n  display() {
    console.log('Stack:', this.items);
  }
}
\n// Example usage\nconst stack = new Stack(5);\nstack.push(10);\nstack.push(20);\nstack.push(30);\nstack.display(); \n// Stack: [10, 20, 30]\nconsole.log('Peek:', stack.peek()); \n// 30\nconsole.log('Pop:', stack.pop()); \n// 30\nstack.display(); \n// Stack: [10, 20]\n
